  CONSTRAINT `fk_we_workout` FOREIGN KEY (`workout_id`) REFERENCES `Workout` (`workout_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2167 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
