DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_estimated_1rm`(p_weight DECIMAL(6,2), p_reps SMALLINT) RETURNS decimal(6,2)
    NO SQL
    DETERMINISTIC
BEGIN
    IF p_weight IS NULL OR p_reps IS NULL OR p_reps < 1 THEN
        RETURN 0;
    END IF;
    IF p_reps = 1 THEN
        RETURN p_weight;
    END IF;
    RETURN ROUND(p_weight * (1 + (p_reps / 30.0)), 2);
END ;;
DELIMITER ;
