/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP FUNCTION IF EXISTS `fn_weekly_volume` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = latin1 */ ;
/*!50003 SET character_set_results = latin1 */ ;
/*!50003 SET collation_connection  = latin1_swedish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_weekly_volume`(p_user_id INT, p_date DATE) RETURNS decimal(12,2)
    READS SQL DATA
BEGIN
    DECLARE v_total DECIMAL(12,2);

    SELECT COALESCE(SUM(s.reps * s.weight_kg), 0)
      INTO v_total
      FROM SetEntry        s
      JOIN WorkoutExercise we ON s.workout_exercise_id = we.workout_exercise_id
      JOIN Workout         w  ON we.workout_id         = w.workout_id
     WHERE w.user_id  = p_user_id
       AND s.is_warmup = FALSE
       AND YEARWEEK(w.started_at, 3) = YEARWEEK(p_date, 3);

    RETURN v_total;
END ;;
DELIMITER ;
