/*!50003 DROP PROCEDURE IF EXISTS `sp_finish_workout` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = latin1 */ ;
/*!50003 SET character_set_results = latin1 */ ;
/*!50003 SET collation_connection  = latin1_swedish_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_finish_workout`(IN p_workout_id INT, IN p_notes VARCHAR(255))
    MODIFIES SQL DATA
BEGIN
    DELETE we FROM WorkoutExercise we
     WHERE we.workout_id = p_workout_id
       AND NOT EXISTS (SELECT 1 FROM SetEntry s
                        WHERE s.workout_exercise_id = we.workout_exercise_id);

    UPDATE Workout
       SET ended_at = NOW(),
           notes    = COALESCE(p_notes, notes)
     WHERE workout_id = p_workout_id;
END ;;
DELIMITER ;
